package com.catalogix.audit.model; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="audit_entries",indexes={@Index(name="idx_audit_entity",columnList="entity_type,entity_id"),@Index(name="idx_audit_actor",columnList="actor_user_id")}) public class AuditEntry{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="actor_user_id") Long actorUserId; @Column(nullable=false,length=80) String action; @Column(name="entity_type",nullable=false,length=60) String entityType; @Column(name="entity_id",length=80) String entityId; @Column(length=1000) String details; @Column(name="occurred_at",nullable=false) Instant occurredAt=Instant.now(); public Long getId(){return id;} public Long getActorUserId(){return actorUserId;} public String getAction(){return action;} public String getEntityType(){return entityType;} public String getEntityId(){return entityId;} public String getDetails(){return details;} public Instant getOccurredAt(){return occurredAt;} public void setActorUserId(Long v){actorUserId=v;} public void setAction(String v){action=v;} public void setEntityType(String v){entityType=v;} public void setEntityId(String v){entityId=v;} public void setDetails(String v){details=v;} public void setOccurredAt(Instant v){occurredAt=v;} }
